package org.icu.sepsis.deterioration;
import java.time.*;import java.util.*;import javax.validation.constraints.*;
import org.icu.sepsis.api.ApiException;import org.icu.sepsis.application.Store;import org.icu.sepsis.domain.Domain.*;
import org.springframework.stereotype.Service;import org.springframework.data.mongodb.core.mapping.Document;import org.springframework.data.mongodb.core.query.*;import org.springframework.data.domain.Sort;import org.springframework.data.mongodb.core.FindAndModifyOptions;
@Service public class SpecialtyEvidenceService {
 @org.springframework.beans.factory.annotation.Autowired private org.springframework.beans.factory.ObjectProvider<org.icu.sepsis.integration.SmartCareSourceReader> patientSource;
 private final Store store;public SpecialtyEvidenceService(Store store){this.store=store;}
 @Document("sepsis_specialty_evidence") public static class Record extends Base {public String module,actor,reason;public long sequence;public Map<String,Value> values;public boolean withdrawn;}
 public static class Value {public Double number;public Boolean flag;public String choice,unit;public Instant observedAt;@Size(max=200) public String reference;}
 public static class Request {@NotBlank public String encounterId;@NotBlank @Size(max=500) public String reason;public String expectedId;public boolean withdrawn;@javax.validation.Valid public Map<String,Value> values=new LinkedHashMap<>();}
 private static boolean fresh(Value v,String field,Instant now){Duration age=field.equals("baseline")?Duration.ofDays(365):field.equals("pf")||field.equals("sf")||field.equals("sfValid")||field.equals("measurementValid")||field.equals("peep")||field.equals("flow")||field.equals("support")?Duration.ofHours(1):field.equals("rass")?Duration.ofHours(4):Duration.ofDays(1);return v!=null&&v.observedAt!=null&&!v.observedAt.isAfter(now)&&!v.observedAt.isBefore(now.minus(age));}
 private static String fieldLabel(String module,String field){return Arrays.stream(SpecialtyRules.FIELDS.get(module)).map(f->f.split("\\|")).filter(a->a[0].equals(field)).map(a->a[1]).findFirst().orElse(field);}
 private static void issue(List<Map<String,Object>> issues,String module,String field,String status,String message){issues.add(Map.of("field",field,"fieldLabel",fieldLabel(module,field),"status",status,"message",message));}
 private static String normalizedUnit(String unit){if(unit==null)return "";String u=unit.trim().toLowerCase(java.util.Locale.ROOT).replace("µ","μ").replace("／","/").replace(" ","").replace("×10^9","10^9").replace("x10^9","10^9").replace("10⁹","10^9");return u.equals("umol/l")?"μmol/l":u;}
 private Record latest(Patient p,String module,Instant now){return store.db.findOne(Query.query(Criteria.where("patientId").is(p.id).and("encounterId").is(p.encounterId).and("department").is(p.department).and("module").is(module).and("createdAt").lte(now)).with(Sort.by(Sort.Direction.DESC,"sequence","createdAt")),Record.class);}
 public Record record(Patient p,String module,Request req,String actor,Instant now){if(!SpecialtyRules.FIELDS.containsKey(module))throw ApiException.notFound();if(!p.encounterId.equals(req.encounterId))throw ApiException.conflict("住院上下文变化");Record previous=latest(p,module,now);if(!Objects.equals(req.expectedId,previous==null?null:previous.id))throw ApiException.conflict("临床复核已变化，请刷新");
  var defs=new HashMap<String,String>();for(String f:SpecialtyRules.FIELDS.get(module)){var a=f.split("\\|");defs.put(a[0],a[2]);}
  if(req.values==null||(!req.withdrawn&&req.values.isEmpty())||req.values.size()>defs.size())throw ApiException.conflict("复核字段无效");
  for(var entry:req.values.entrySet()){var v=entry.getValue();var unit=defs.get(entry.getKey());if(unit==null||v==null||v.observedAt==null||v.observedAt.isAfter(now)||v.observedAt.isBefore(now.minus(Duration.ofDays(entry.getKey().equals("baseline")?365:1))))throw ApiException.conflict("字段或观察时间无效");if(v.reference==null||v.reference.isBlank()||v.reference.length()>200)throw ApiException.conflict("每项证据需注明可核对的来源");
   if(unit.equals("bool")){if(v.flag==null||v.number!=null||v.choice!=null)throw ApiException.conflict("临床判断须明确是或否");}
   else if(unit.equals("support")){if(!Set.of("invasive","niv","hfno").contains(v.choice==null?"":v.choice)||v.number!=null||v.flag!=null)throw ApiException.conflict("呼吸支持类型无效");}
   else if(v.number==null||!Double.isFinite(v.number)||!unit.equals(v.unit)||v.flag!=null||v.choice!=null||(!Set.of("rass","rise48h").contains(entry.getKey())&&v.number<0)||Set.of("pf","baseline","currentCreatinine").contains(entry.getKey())&&v.number<=0||entry.getKey().equals("rass")&&(v.number< -5||v.number>4||v.number!=Math.rint(v.number)))throw ApiException.conflict("数值或单位不匹配");
  }
  var r=new Record();store.init(r,p,now);r.module=module;r.actor=actor;r.reason=req.reason.trim();r.values=req.values;r.withdrawn=req.withdrawn;
  String seqKey=store.fingerprint("specialty-sequence",List.of(p.id,p.encounterId,p.department,module));var headCriteria=Criteria.where("_id").is(seqKey);if(previous==null)headCriteria.and("headId").exists(false);else headCriteria.and("headId").is(previous.id);
  ReviewedLabEvidenceService.Sequence seq;try{seq=store.db.findAndModify(Query.query(headCriteria),new Update().inc("sequence",1).set("headId",r.id),FindAndModifyOptions.options().upsert(previous==null).returnNew(true),ReviewedLabEvidenceService.Sequence.class);}catch(org.springframework.dao.DuplicateKeyException changed){throw ApiException.conflict("复核已被其他人更新，请刷新");}
  if(seq==null)throw ApiException.conflict("复核已变化，请刷新");r.sequence=seq.sequence;
  try{store.db.insert(r);}catch(RuntimeException failed){var rollback=previous==null?new Update().unset("headId"):new Update().set("headId",previous.id);store.db.updateFirst(Query.query(Criteria.where("_id").is(seqKey).and("headId").is(r.id)),rollback,ReviewedLabEvidenceService.Sequence.class);throw failed;}return r;
 }
 public Map<String,Object> assess(Patient p,Instant now,List<Observation> rows,Map<String,Object> aki){java.time.LocalDate birth=p.birthDate;if(birth==null&&patientSource!=null)try{var source=patientSource.getIfAvailable();if(source!=null){var actual=source.loadPatient(p.id);if(Objects.equals(actual.encounterId,p.encounterId)&&Objects.equals(actual.department,p.department))birth=actual.birthDate;}}catch(RuntimeException ignored){}final java.time.LocalDate knownBirth=birth;rows=rows.stream().filter(o->Objects.equals(o.patientId,p.id)&&Objects.equals(o.encounterId,p.encounterId)&&Objects.equals(o.department,p.department)).collect(java.util.stream.Collectors.toList());var modules=new ArrayList<Map<String,Object>>();for(String key:SpecialtyRules.FIELDS.keySet()){
  Record review=latest(p,key,now);var values=new LinkedHashMap<String,Object>();var evidence=new ArrayList<Map<String,Object>>();var conflicts=new ArrayList<String>();var reviewIssues=new ArrayList<Map<String,Object>>();
  // Current structured observations are automatically reused; never use unconfirmed HIS reports.
  Map<String,String> codes=key.equals("aki")?Map.of("currentCreatinine","CREA"):key.equals("ards")?Map.of("pf","PF_RATIO"):key.equals("dic")?Map.of("platelets","PLT"):key.equals("delirium")?Map.of("rass","RASS"):Map.of();
  for(var e:codes.entrySet()){var o=OrganContext.latest(rows,e.getValue(),now,Duration.ofHours(e.getKey().equals("rass")?4:e.getKey().equals("pf")?1:24));if(o!=null){String expected=Arrays.stream(SpecialtyRules.FIELDS.get(key)).map(f->f.split("\\|")).filter(a->a[0].equals(e.getKey())).findFirst().orElseThrow()[2];if(normalizedUnit(expected).equals(normalizedUnit(o.unit))||("score".equals(expected)&&o.unit==null)){values.put(e.getKey(),o.value);evidence.add(new LinkedHashMap<>(Map.of("field",e.getKey(),"value",o.value,"unit",expected,"time",o.eventTime,"origin","structured")));}}}
  if(knownBirth!=null&&!knownBirth.isAfter(now.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate()))values.put("adult",java.time.Period.between(knownBirth,now.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate()).getYears()>=18);
  if(review!=null&&!review.withdrawn)for(var e:review.values.entrySet()){var v=e.getValue();if(!fresh(v,e.getKey(),now)){issue(reviewIssues,key,e.getKey(),v==null||v.observedAt==null?"invalid_time":v.observedAt.isAfter(now)?"future":"expired","复核时间不在本次有效窗口，未用于研判");continue;}if("adult".equals(e.getKey())&&values.containsKey("adult")){if(!Objects.equals(values.get("adult"),v.flag)){values.remove("adult");conflicts.add("成人适用性与出生日期资料冲突");issue(reviewIssues,key,e.getKey(),"conflict","与当前出生日期资料冲突，未用于研判");}continue;}if(v.observedAt!=null&&evidence.stream().anyMatch(existing->e.getKey().equals(existing.get("field"))&&((Instant)existing.get("time")).isAfter(v.observedAt))){issue(reviewIssues,key,e.getKey(),"superseded","已有更新的结构化观测，本项复核未用于研判");continue;}Object value=v.flag!=null?v.flag:v.number!=null?v.number:v.choice;if(evidence.stream().anyMatch(existing->e.getKey().equals(existing.get("field"))&&v.observedAt.equals(existing.get("time"))&&!Objects.equals(value,existing.get("value")))){conflicts.add(fieldLabel(key,e.getKey())+"同刻来源冲突，未挑选数值");issue(reviewIssues,key,e.getKey(),"conflict","同刻来源数值冲突，未挑选用于研判");values.remove(e.getKey());evidence.removeIf(existing->e.getKey().equals(existing.get("field")));continue;}evidence.removeIf(existing->e.getKey().equals(existing.get("field")));values.put(e.getKey(),value);var fact=new LinkedHashMap<String,Object>();fact.put("field",e.getKey());fact.put("value",value);fact.put("unit",v.unit);fact.put("time",v.observedAt);fact.put("origin","physician_review");evidence.add(fact);}
  var baselineTime=evidence.stream().filter(e->"baseline".equals(e.get("field"))).map(e->(Instant)e.get("time")).max(Comparator.naturalOrder());var currentTime=evidence.stream().filter(e->"currentCreatinine".equals(e.get("field"))).map(e->(Instant)e.get("time")).max(Comparator.naturalOrder());if(baselineTime.isPresent()&&currentTime.isPresent()&&baselineTime.get().isAfter(currentTime.get())){conflicts.add("基线时间晚于当前肌酐，未用于分期");issue(reviewIssues,key,"baseline","invalid_order","基线时间晚于当前肌酐，未用于分期");values.remove("baseline");evidence.removeIf(e->"baseline".equals(e.get("field")));}
  for(var item:evidence){String id=String.valueOf(item.get("field"));String label=Arrays.stream(SpecialtyRules.FIELDS.get(key)).map(f->f.split("\\|")).filter(a->a[0].equals(id)).map(a->a[1]).findFirst().orElse(id);item.put("fieldLabel",label);}
  var result=SpecialtyRules.evaluate(key,values);
  if(key.equals("aki")&&Boolean.TRUE.equals(values.get("adult"))&&!Boolean.TRUE.equals(values.get("chronicDialysis"))){var urine=aki.get("urine") instanceof Map?(Map<?,?>)aki.get("urine"):Map.of();Integer urineStage=urine.get("stageReference") instanceof Number?((Number)urine.get("stageReference")).intValue():null;Integer crStage=result.get("stage") instanceof Number?((Number)result.get("stage")).intValue():null;result.put("creatinineStage",crStage);result.put("urineStage",urineStage);result.put("stageIsLowerBound",true);if(urineStage!=null||crStage!=null){int stage=Math.max(urineStage==null?0:urineStage,crStage==null?0:crStage);result.put("stage",stage);result.put("status","candidate");result.put("detail","已提供路径至少达到 "+stage+" 期参考；不完整路径及RRT/基线仍需核对，非最终临床分期");}}
result.put("reviewIssues",reviewIssues);result.put("conflicts",conflicts);if(!conflicts.isEmpty())result.put("detail",result.get("detail")+"；"+String.join("；",conflicts));result.put("reviewValues",review==null||review.withdrawn?Map.of():review.values);result.put("evidence",evidence);result.put("reviewId",review==null?null:review.id);result.put("reviewedAt",review==null?null:review.createdAt);result.put("reviewer",review==null?null:review.actor);result.put("withdrawn",review!=null&&review.withdrawn);modules.add(result);
 }return Map.of("modules",modules,"schema",SpecialtyRules.schema());}
}
